    #[test]
    fn multi_char_without_space_prefix() {
        assert!(!check_if_last_char_is_a_letter("HelloA"));
        assert!(!check_if_last_char_is_a_letter("A!"));
    }

    #[test]
    fn unicode_characters() {
        // The last char 'ç' is not ASCII, so false.
        assert!(!check_if_last_char_is_a_letter("façade"));
        // But if last is ASCII letter preceded by a space, it's true.
        assert!(check_if_last_char_is_a_letter("olá a"));
    }
